def build_list(n):
    result = []
    for i in range(n):
        result.append(i * 2)
    return result

def process(arr):
    total = 0                    # O(1)
    for i in range(len(arr)):    # O(n)
        for j in range(len(arr)):# O(n)
            total += arr[i] * arr[j]
    return total
